-- Source: $HOME/.config/hypr/wallust/wallust-hyprland.conf — convert this file to Lua and ensure it is on Lua's package.path.
require("wallust.wallust-hyprland")

-- translucent blurred menu bar
hl.layer_rule({ match = { namespace = "waybar" }, blur = true })

-- blur only the visible (rounded) part, not the transparent corners
hl.layer_rule({ match = { namespace = "vicinae" }, blur = true, ignore_alpha = 0.3 })
hl.layer_rule({ match = { namespace = "^swaync-(control-center|notification-window)$" }, blur = true, ignore_alpha = 0.3 })

hl.window_rule({
    match = {
        class = "^([Cc]ode|com\\.microsoft\\.VSCode)$",
    },
    opacity = "0.9 0.85",
})

-- apps like kitty request maximize on open; keep them tiled
hl.window_rule({ match = { class = ".*" }, suppress_event = "maximize" })


hl.config({
    general = {
        border_size = 1,
        gaps_in = 8,
        gaps_out = 20,
        col = {
            active_border = "rgba(ffffff40)",
            inactive_border = "rgba(ffffff1a)",
        },
    },
    decoration = {
        rounding = 16,
        rounding_power = 4.0,
        active_opacity = 1.0,
        inactive_opacity = 1.0,
        fullscreen_opacity = 1.0,
        dim_inactive = true,
        dim_strength = 0,
        dim_special = 0.2,
        shadow = {
            enabled = true,
            range = 25,
            render_power = 3,
            color = "rgba(00000066)",
            color_inactive = "rgba(00000033)",
        },
        blur = {
            enabled = true,
            size = 10,
            passes = 2,
            ignore_opacity = true,
            new_optimizations = true,
            special = true,
            popups = true,
        },
    },
    group = {
        col = {
            border_active = color15,
        },
        groupbar = {
            col = {
                active = color0,
            },
        },
    },
    -- translucent blurred menu bar
    -- blur only the visible (rounded) part, not the transparent corners
    -- VS Code: translucent with blur behind, a bit more when unfocused
})


-- satty annotation editor opens over the current layout instead of tiling into it
hl.window_rule({ match = { class = "^(com\\.gabm\\.satty)$" }, float = true, center = true })
